mapper.select:
SELECT p.id, p.patient_no, p.name, p.gender, p.birthday, p.id_card, p.phone, p.address, p.disease_type, p.diagnosis_date, p.current_doctor_id, p.risk_level, p.status, u.name AS doctor_name, rlc.level_name AS risk_level_name FROM patient p LEFT JOIN doctor d ON p.current_doctor_id = d.id LEFT JOIN user u ON d.user_id = u.id LEFT JOIN risk_level_config rlc ON p.risk_level = rlc.level_code
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.patient_no LIKE CONCAT('%', #{patientNo}, '%')
AND p.disease_type LIKE CONCAT('%', #{diseaseType}, '%')
AND p.risk_level = #{riskLevel}
AND p.current_doctor_id = #{doctorId}
ORDER BY p.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM patient p
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.patient_no LIKE CONCAT('%', #{patientNo}, '%')
AND p.disease_type LIKE CONCAT('%', #{diseaseType}, '%')
AND p.risk_level = #{riskLevel}
AND p.current_doctor_id = #{doctorId}

mapper.update:
UPDATE patient
name = #{name}, gender = #{gender}, birthday = #{birthday}, id_card = #{idCard}, phone = #{phone}, address = #{address}, disease_type = #{diseaseType}, diagnosis_date = #{diagnosisDate}, current_doctor_id = #{currentDoctorId}, risk_level = #{riskLevel}, status = #{status},
WHERE id = #{id}
